/** Shape the seed into the runtime catalogue (used in demo mode). */
export function demoCatalog(): ServiceCategory[] {
  return SEED_CATEGORIES.map((c, ci) => ({
    id: `demo-cat-${c.slug}`,
    slug: c.slug,
    name: c.name,
    tagline: c.tagline,
    description: c.description,
    icon: c.icon,
    sort_order: ci + 1,
    is_active: true,
    services: c.services.map((s, si) => ({
      id: `demo-svc-${s.slug}`,
      category_id: `demo-cat-${c.slug}`,
      slug: s.slug,
      name: s.name,
      short_description: s.short,
      description: s.description,
      icon: s.icon,
      image_url: null,
      starting_price: null,
      is_active: true,
      sort_order: si + 1,
    })),
  }));
}
